ited(address,address,uint256,uint256,uint256)":{"notice":"Emitted when collateral is deposited"},"CollateralFactorUpdated(uint256,uint256)":{"notice":"Emitted when CF is updated"},"CollateralWithdrawn(address,address,uint256,uint256,uint256)":{"notice":"Emitted when collateral is withdrawn"},"DepositTokenActiveUpdated(bool)":{"notice":"Emitted when active flag is updated"},"MaxTotalSupplyUpdated(uint256,uint256)":{"notice":"Emitted when max total supply is updated"}},"kind":"user","methods":{"approve(address,uint256)":{"notice":"Set `amount` as the allowance of `spender` over the caller's tokens"},"collateralFactor()":{"notice":"Collateral factor for the deposit token"},"decimals()":{"notice":"The decimals of the token"},"decreaseAllowance(address,uint256)":{"notice":"Atomically decrease the allowance granted to `spender` by the caller"},"deposit(uint256,address)":{"notice":"Deposit collateral and mint msdTOKEN (tokenized deposit position)"},"flashWithdraw(address,uint256)":{"notice":"Burn msdTOKEN, withdraw collateral and transfer to `_msgSender()` (i.e. SmartFarmingManager)"},"governor()":{"notice":"Get the governor"},"increaseAllowance(address,uint256)":{"notice":"Atomically increase the allowance granted to `spender` by the caller"},"isActive()":{"notice":"If a collateral isn't active, it disables minting new tokens"},"lockedBalanceOf(address)":{"notice":"Get the locked balance"},"maxTotalSupply()":{"notice":"The supply cap (in USD)"},"name()":{"notice":"The name of the token"},"pool()":{"notice":"Pool contract"},"poolRegistry()":{"notice":"Get pool registry contract"},"quoteDepositIn(uint256)":{"notice":"Quote gross `_amount` to deposit `amountToDeposit_` collateral"},"quoteDepositOut(uint256)":{"notice":"Quote collateral `_amountToDeposit` by using gross `amount_`"},"quoteWithdrawIn(uint256)":{"notice":"Quote gross `_amount` to withdraw `amountToWithdraw_` collateral"},"quoteWithdrawOut(uint256)":{"notice":"Quote collateral `_amountToWithdraw` by using gross `_amount`"},"seize(address,address,uint256)":{"notice":"Seize tokens"},"sweep(address,address,uint256)":{"notice":"ERC20 recovery in case of stuck tokens due direct transfers to the contract address."},"symbol()":{"notice":"The symbol of the token"},"toggleIsActive()":{"notice":"Enable/Disable the Deposit Token"},"underlying()":{"notice":"Deposit underlying asset (e.g. MET)"},"unlockedBalanceOf(address)":{"notice":"Get the unlocked balance (i.e. transferable, withdrawable)"},"updateCollateralFactor(uint128)":{"notice":"Update collateral factor"},"updateMaxTotalSupply(uint256)":{"notice":"Update max total supply"},"withdraw(uint256,address)":{"notice":"Burn msdTOKEN and withdraw collateral"},"withdrawFrom(address,uint256)":{"notice":"Burn msdTOKEN and withdraw collateral from a given account"}},"version":1}},"settings":{"compilationTarget":{"contracts/DepositToken.sol":"DepositToken"},"evmVersion":"cancun","libraries":{},"metadata":{"bytecodeHash":"ipfs","useLiteralContent":true},"optimizer":{"enabled":true,"runs":200},"remappings":[]},"sources":{"contracts/DepositToken.sol":{"content":"// SPDX-License-Identifier: MIT

pragma solidity 0.8.24;

import {IERC20} from "./dependencies/openzeppelin/token/ERC20/IERC20.sol";
import {SafeERC20} from "./dependencies/openzeppelin/token/ERC20/utils/SafeERC20.sol";
import {Initializable} from "./dependencies/openzeppelin-upgradeable/proxy/utils/Initializable.sol";
import {Math} from "./dependencies/openzeppelin/utils/math/Math.sol";
import {Manageable, SenderIsNotPool} from "./access/Manageable.sol";
import {ReentrancyGuardDeprecated} from "./utils/ReentrancyGuardDeprecated.sol";
import {ReentrancyGuardTransient} from "./utils/ReentrancyGuardTransient.sol";
import {TokenHolder} from "./utils/TokenHolder.sol";
import {WadRayMath} from "./lib/WadRayMath.sol";
import {IRewardsDistributor} from "./interfaces/IRewardsDistributor.sol";
import {IPool} from "./interfaces/IPool.sol";
import {DepositTokenStorageV1} from "./storage/DepositTokenStorage.sol";

error CollateralIsInexistent();
error DepositTokenIsInactive();
error NotEnoughFreeBalance();
error UnderlyingAssetIsNull();
error PoolIsNull();
error SymbolIsNull();
error DecimalsIsNull();
error CollateralFactorTooHigh();
error CollateralFactorTooLow();
error DecreasedAllowanceBelowZero();
error AmountIsZero();
error BeneficiaryIsNull();
error AmountExceedsAllowance();
error RecipientIsNull();
error ApproveFromTheZeroAddress();
error ApproveToTheZeroAddress();
error BurnFromTheZeroAddress();
error BurnAmountExceedsBalance();
error MintToTheZeroAddress();
error SurpassMaxDepositSupply();
error TransferFromTheZeroAddress();
error TransferToTheZeroAddress();
error TransferAmountExceedsBalance();
error NewValueIsSameAsCurrent();
error SenderIsNotSmartFarmingManager();
error TreasuryCanNotDeposit();

/**
 * @title Represents the users' deposits
 */
contract DepositToken is
    Initializable,
    ReentrancyGuardDeprecated,
    ReentrancyGuardTransient,
    TokenHolder,
    Manageable,
    DepositTokenStorageV1
{
    using SafeERC20 for IERC20;
    using WadRayMath for uint256;

    string public constant VERSION = "1.3.2";

    /// @notice Emitted when collateral is deposited
    event CollateralDeposited(
        address indexed from,
        address indexed account,
        uint256 amount,
        uint256 deposited,
        uint256 fee
    );

    /// @notice Emitted when CF is updated
    event CollateralFactorUpdated(uint256 oldCollateralFactor, uint256 newCollateralFactor);

    /// @notice Emitted when collateral is withdrawn
    event CollateralWithdrawn(
        address indexed account,
        address indexed to,
        uint256 amount,
        uint256 withdrawn,
        uint256 fee
    );

    /// @notice Emitted when active flag is updated
    event DepositTokenActiveUpdated(bool newActive);

    /// @notice Emitted when max total supply is updated
    event MaxTotalSupplyUpdated(uint256 oldMaxTotalSupply, uint256 newMaxTotalSupply);

    /**
     * @dev Throws if sender is SmartFarmingManager
     */
    modifier onlyIfSmartFarmingManager() {
        if (_msgSender() != address(pool.smartFarmingManager())) revert SenderIsNotSmartFarmingManager();
        _;
    }

    /**
     * @dev Throws if sender can't seize
     */
    modifier onlyIfCanSeize() {
        if (_msgSender() != address(pool)) revert SenderIsNotPool();
        _;
    }

    /**
     * @dev Throws if deposit token doesn't exist
     */
    modifier onlyIfDepositTokenExists() {
        if (!pool.doesDepositTokenExist(this)) revert CollateralIsInexistent();
        _;
    }

    /**
     * @dev Throws if deposit token isn't enabled
     */
    modifier onlyIfDepositTokenIsActive() {
        if (!isActive) revert DepositTokenIsInactive();
        _;
    }

    /**
     * @notice Update reward contracts' states
     * @dev Should be called before balance changes (i.e. mint/burn)
     */
    modifier updateRewardsBeforeMintOrBurn(address account_) {
        address[] memory _rewardsDistributors = pool.getRewardsDistributors();
        uint256 _length = _rewardsDistributors.length;
        for (uint256 i; i < _length; ++i) {
            IRewardsDistributor(_rewardsDistributors[i]).updateBeforeMintOrBurn(this, account_);
        }
        _;
    }

    /**
     * @notice Update reward contracts' states
     * @dev Should be called before balance changes (i.e. transfer)
     */
    modifier updateRewardsBeforeTransfer(address sender_, address recipient_) {
        address[] memory _rewardsDistributors = pool.getRewardsDistributors();
        uint256 _length = _rewardsDistributors.length;
        for (uint256 i; i < _length; ++i) {
            IRewardsDistributor(_rewardsDistributors[i]).updateBeforeTransfer(this, sender_, recipient_);
        }
        _;
    }

    constructor() {
        _disableInitializers();
    }

    function initialize(
        IERC20 underlying_,
        IPool pool_,
        string calldata name_,
        string calldata symbol_,
        uint8 decimals_,
        uint128 collateralFactor_,
        uint256 maxTotalSupply_
    ) external initializer {
        if (address(underlying_) == address(0)) revert UnderlyingAssetIsNull();
        if (address(pool_) == address(0)) revert PoolIsNull();
        if (bytes(symbol_).length == 0) revert SymbolIsNull();
        if (decimals_ == 0) revert DecimalsIsNull();
        if (collateralFactor_ == 0) revert CollateralFactorTooLow();
        if (collateralFactor_ >= 1e18) revert CollateralFactorTooHigh();

        __Manageable_init(pool_);

        name = name_;
        symbol = symbol_;
        underlying = underlying_;
        isActive = true;
        decimals = decimals_;
        collateralFactor = collateralFactor_;
        maxTotalSupply = maxTotalSupply_;
    }

    /**
     * @notice Requires that amount is lower than the account's unlocked balance
     */
    function _revertIfLocked(address account_, uint256 amount_) private view {
        if (unlockedBalanceOf(account_) < amount_) revert NotEnoughFreeBalance();
    }

    /**
     * @notice Set `amount` as the allowance of `spender` over the caller's tokens
     */
    function approve(address spender_, uint256 amount_) external override returns (bool) {
        _approve(_msgSender(), spender_, amount_);
        return true;
    }

    /**
     * @notice Atomically decrease the allowance granted to `spender` by the caller
     */
    function decreaseAllowance(address spender_, uint256 subtractedValue_) external returns (bool) {
        address _msgSender = _msgSender();
        uint256 _currentAllowance = allowance[_msgSender][spender_];
        if (_currentAllowance < subtractedValue_) revert DecreasedAllowanceBelowZero();
        unchecked {
            _approve(_msgSender, spender_, _currentAllowance - subtractedValue_);
        }
        return true;
    }

    /**
     * @notice Deposit collateral and mint msdTOKEN (tokenized deposit position)
     * @param amount_ The amount of collateral tokens to deposit
     * @param onBehalfOf_ The account to deposit to
     * @return _deposited The amount deposited after fees
     */
    function deposit(
        uint256 amount_,
        address onBehalfOf_
    ) external override whenNotPaused nonReentrant onlyIfDepositTokenExists returns (uint256 _deposited, uint256 _fee) {
        if (amount_ == 0) revert AmountIsZero();
        if (onBehalfOf_ == address(0)) revert BeneficiaryIsNull();

        IPool _pool = pool;
        IERC20 _underlying = underlying;
        address _msgSender = _msgSender();
        address _treasury = address(_pool.treasury());

        if (_msgSender == _treasury) revert TreasuryCanNotDeposit();

        uint256 _balanceBefore = _underlying.balanceOf(_treasury);
        _underlying.safeTransferFrom(_msgSender, _treasury, amount_);
        amount_ = _underlying.balanceOf(_treasury) - _balanceBefore;

        (_deposited, _fee) = quoteDepositOut(amount_);
        if (_fee > 0) {
            _mint(_pool.feeCollector(), _fee);
        }

        _mint(onBehalfOf_, _deposited);

        emit CollateralDeposited(_msgSender, onBehalfOf_, amount_, _deposited, _fee);
    }

    /**
     * @notice Burn msdTOKEN, withdraw collateral and transfer to `_msgSender()` (i.e. SmartFarmingManager)
     * @param account_ The account where deposit token will be burnt from
     * @param amount_ The amount of collateral to withdraw
     * @return _withdrawn The amount withdrawn after fees
     */
    function flashWithdraw(
        address account_,
        uint256 amount_
    ) external override onlyIfSmartFarmingManager returns (uint256 _withdrawn, uint256 _fee) {
        return _withdraw({account_: account_, amount_: amount_, to_: _msgSender()});
    }

    /**
     * @notice Atomically increase the allowance granted to `spender` by the caller
     */
    function increaseAllowance(address spender_, uint256 addedValue_) external returns (bool) {
        address _msgSender = _msgSender();
        _approve(_msgSender, spender_, allowance[_msgSender][spender_] + addedValue_);
        return true;
    }

    /**
     * @notice Get the locked balance
     * @param account_ The account to check
     * @return _lockedBalance The locked amount
     */
    function lockedBalanceOf(address account_) external view override returns (uint256 _lockedBalance) {
        unchecked {
            return balanceOf[account_] - unlockedBalanceOf(account_);
        }
    }

    /**
     * @notice Quote gross `_amount` to deposit `amountToDeposit_` collateral
     * @param amountToDeposit_ Collateral to deposit
     * @return _amount Gross amount
     * @return _fee Fee amount to collect
     */
    function quoteDepositIn(uint256 amountToDeposit_) external view override returns (uint256 _amount, uint256 _fee) {
        uint256 _depositFee = pool.feeProvider().depositFee();
        if (_depositFee == 0) {
            return (amountToDeposit_, _fee);
        }

        _amount = amountToDeposit_.wadDiv(1e18 - _depositFee);
        _fee = _amount - amountToDeposit_;
    }

